import { readFileSync } from "fs";

const [first, second] = readFileSync(0, "utf8").trim().split("\n");
const [n, k] = first.split(" ").map(Number);
const h = second.split(" ").map(Number);

// dp[i] = 足場 i（0 始まり）にたどり着くまでの最小コスト
const dp = new Array(n).fill(Infinity);
dp[0] = 0;
for (let i = 1; i < n; i++) {
  // 直前の最大 K 個の足場から跳んでくる
  for (let j = Math.max(0, i - k); j < i; j++) {
    dp[i] = Math.min(dp[i], dp[j] + Math.abs(h[i] - h[j]));
  }
}
console.log(dp[n - 1]);
